#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "mvt.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;
  /* Precompute 1/n in the working precision to replace
     repeated divisions with cheaper multiplications. */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      /* For 0 <= i < n, (i % n) == i, so we can drop the modulus here. */
      x1[i]  = (DATA_TYPE)i * inv_n;
      x2[i]  = (DATA_TYPE)((i + 1) % n) * inv_n;
      y_1[i] = (DATA_TYPE)((i + 3) % n) * inv_n;
      y_2[i] = (DATA_TYPE)((i + 4) % n) * inv_n;

      /* Use a row pointer to make the inner initialization loop
         slightly clearer and as cache-friendly as the original. */
      DATA_TYPE *Ai = A[i];
      for (j = 0; j < n; j++)
        Ai[j] = (DATA_TYPE)((i * j) % n) * inv_n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Local restrict-qualified aliases to help the compiler with
     vectorization and alias analysis.  In this benchmark the
     arrays are allocated disjointly in main(), so this is a
     valid assumption. */
  DATA_TYPE *restrict x1r = x1;
  DATA_TYPE *restrict x2r = x2;
  DATA_TYPE *restrict y1r = y_1;
  DATA_TYPE *restrict y2r = y_2;
  DATA_TYPE (*restrict Ar)[n] = A;

#pragma scop
  /* Fused computation of:
   *   x1 = x1 + A  * y_1
   *   x2 = x2 + A^T * y_2
   *
   * Original code:
   *   for i
   *     for j
   *       x1[i] += A[i][j] * y_1[j];
   *   for i
   *     for j
   *       x2[i] += A[j][i] * y_2[j];
   *
   * Here we traverse each element A[i][j] once and perform both
   * updates:
   *   - x1[i] with A[i][j] * y_1[j]
   *   - x2[j] with A[i][j] * y_2[i]
   *
   * This keeps all accesses to A row-contiguous, improves cache
   * locality, and roughly halves the number of matrix elements
   * fetched from memory, while computing the same mathematical
   * result.
   */
  for (i = 0; i < _PB_N; ++i)
  {
    DATA_TYPE *restrict Ai = Ar[i];
    DATA_TYPE sum1 = x1r[i];      /* accumulate x1[i] in a register */
    const DATA_TYPE yi2 = y2r[i]; /* y_2[i] reused for the whole row */

    /* Inner loop has unit-stride access to Ai[j], y_1[j] and x2[j],
       which is friendly to both cache and SIMD units. */
    for (j = 0; j < _PB_N; ++j)
    {
      const DATA_TYPE a_ij = Ai[j];
      sum1   += a_ij * y1r[j];   /* contribution to x1[i] */
      x2r[j] += a_ij * yi2;      /* contribution to x2[j] */
    }

    x1r[i] = sum1;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
