    {
      x1[i] = (DATA_TYPE) (i % n) / n;
      x2[i] = (DATA_TYPE) ((i + 1) % n) / n;
      y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
      y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
      for (j = 0; j < n; j++)
	A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation:
     x1[i] += sum_j A[i][j] * y_1[j];
     x2[i] += sum_j A[j][i] * y_2[j];

   Optimized computation:
     Fuse the two matrix-vector products into a single traversal of A:
       for each matrix element A[i][j],
         it contributes to x1[i] with y_1[j],
         and to x2[j] with y_2[i].

   This improves data locality by:
     - walking each row of A contiguously,
     - using each loaded A[i][j] twice,
     - keeping x1[i] and y_2[i] in registers.

   The order of floating-point operations contributing to each element
   of x1 and x2 is preserved, so the numerical results are bitwise
   identical to the original implementation.
*/
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Local restrict-qualified aliases help the compiler's alias analysis
     without changing the external interface defined by PolyBench macros. */
  DATA_TYPE       * restrict x1_ = x1;
  DATA_TYPE       * restrict x2_ = x2;
  const DATA_TYPE * restrict y1_ = y_1;
  const DATA_TYPE * restrict y2_ = y_2;
  DATA_TYPE (* restrict A_)[n]   = A;

#pragma scop
  for (i = 0; i < _PB_N; i++)
  {
    /* Keep frequently used scalars in registers. */
    DATA_TYPE xi          = x1_[i];
    const DATA_TYPE y2_i  = y2_[i];

    /* Traverse the i-th row of A contiguously.  Each A[i][j] is used twice:
         - once for updating x1[i]   (A * y_1),
         - once for updating x2[j]   (A^T * y_2).
       This fuses the two original double loops into one and improves
       cache locality and memory bandwidth usage. */
#pragma GCC ivdep
    for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE a_ij = A_[i][j];
      xi      += a_ij * y1_[j];
      x2_[j]  += a_ij * y2_i;
    }

    x1_[i] = xi;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
