    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version notes:
   - We fuse the two matrix-vector products so that each A[i][j] is
     loaded only once and contributes to both x1 and x2.
   - We apply 2D tiling (blocking) on (i,j) to improve cache locality.
   - We create local restrict-qualified pointers to help the compiler
     with alias analysis and vectorization. PolyBench benchmarks
     are designed so that the input arrays do not alias.
   - The order of floating‑point operations contributing to each
     x1[i] and x2[i] is preserved (j increases for x1, i increases for x2),
     so numerical results remain bitwise identical for non‑aliased inputs.
 */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Loop indices. */
  int i, j;
  int ii, jj;

  /* PolyBench uses _PB_N as the (possibly instrumented) problem size. */
  const int n_ = _PB_N;

  /* Local restrict-qualified views of the arrays.
     This matches the benchmark's intent (no aliasing between arrays) and
     enables better optimization by the compiler. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x1_ = x1;
  DATA_TYPE *restrict x2_ = x2;
  DATA_TYPE *restrict y1_ = y_1;
  DATA_TYPE *restrict y2_ = y_2;

  /* Tile sizes chosen to keep a block of A plus relevant x2/y1 slices in L1. */
  const int T_I = 32;
  const int T_J = 32;

#pragma scop
  /* Fused, tiled computation of:
       x1[i] += sum_j A[i][j] * y1[j]
       x2[j] += sum_i A[i][j] * y2[i]
     We iterate over tiles in (i,j), then rows i within a tile, then
     columns j within each row-tile. */
  for (ii = 0; ii < n_; ii += T_I)
  {
    const int i_end = (ii + T_I < n_) ? (ii + T_I) : n_;

    for (i = ii; i < i_end; ++i)
    {
      /* Keep x1[i] and y2[i] in registers across j-tiles. */
      DATA_TYPE x1_i = x1_[i];
      const DATA_TYPE y2_i = y2_[i];

      for (jj = 0; jj < n_; jj += T_J)
      {
        const int j_end = (jj + T_J < n_) ? (jj + T_J) : n_;

        /* Pointers to the current tile segment. */
        DATA_TYPE *restrict Ai        = &A_[i][jj];   /* A[i][jj .. j_end) */
        DATA_TYPE *restrict x2_block  = &x2_[jj];     /* x2[jj .. j_end)   */
        DATA_TYPE *restrict y1_block  = &y1_[jj];     /* y1[jj .. j_end)   */

        const int len = j_end - jj;
        int j_local = 0;

        /* Manually unrolled inner loop (factor 4) to increase ILP and
           help vectorization, while preserving the order of operations. */
        for (; j_local + 3 < len; j_local += 4)
        {
          const DATA_TYPE a0 = Ai[j_local    ];
          const DATA_TYPE a1 = Ai[j_local + 1];
          const DATA_TYPE a2 = Ai[j_local + 2];
          const DATA_TYPE a3 = Ai[j_local + 3];

          x1_i += a0 * y1_block[j_local    ];
          x2_block[j_local    ] += a0 * y2_i;

          x1_i += a1 * y1_block[j_local + 1];
          x2_block[j_local + 1] += a1 * y2_i;

          x1_i += a2 * y1_block[j_local + 2];
          x2_block[j_local + 2] += a2 * y2_i;

          x1_i += a3 * y1_block[j_local + 3];
          x2_block[j_local + 3] += a3 * y2_i;
        }

        /* Clean up remaining elements in this tile. */
        for (; j_local < len; ++j_local)
        {
          const DATA_TYPE a = Ai[j_local];
          x1_i              += a * y1_block[j_local];
          x2_block[j_local] += a * y2_i;
        }
      }

      /* Write back the accumulated value for this row. */
      x1_[i] = x1_i;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
