/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Use the PolyBench problem-size macro as loop bound. */
  const int n_pb = _PB_N;

  /* Create local restrict-qualified pointers to help the compiler
     optimize and vectorize the kernel.  PolyBench allocates each of
     these arrays separately, so they do not alias. */
  DATA_TYPE *restrict x1_ = x1;
  DATA_TYPE *restrict x2_ = x2;
  const DATA_TYPE *restrict y1_ = y_1;
  const DATA_TYPE *restrict y2_ = y_2;
  const DATA_TYPE *restrict A_  = &A[0][0]; /* row-major contiguous data */

  int i, j;

#pragma scop
  /* First matrix-vector product: x1 += A * y1
     - Traverse A row-wise (good spatial locality).
     - Keep the accumulator for x1[i] in a register to avoid repeated
       loads/stores to memory.  The arithmetic order for each x1[i]
       is identical to the original code. */
  for (i = 0; i < n_pb; i++)
    {
      DATA_TYPE xi = x1_[i];
      const DATA_TYPE *Arow = A_ + (size_t)i * n; /* row i of A */

      for (j = 0; j < n_pb; j++)
        xi += Arow[j] * y1_[j];

      x1_[i] = xi;
    }

  /* Second matrix-vector product: x2 += A^T * y2
     Original code:
       for (i = 0; i < _PB_N; i++)
         for (j = 0; j < _PB_N; j++)
           x2[i] = x2[i] + A[j][i] * y_2[j];

     Here we:
       - Interchange the loops so that j is outer and i is inner.
         For each fixed i, the updates to x2[i] still occur in
         strictly increasing j order, so the floating-point reduction
         order for every element x2[i] is exactly the same as in the
         original program.
       - This loop interchange lets us traverse A row-wise (row j),
         which matches the row-major layout and greatly improves
         spatial locality and cache behavior. */
  for (j = 0; j < n_pb; j++)
    {
      const DATA_TYPE y2j = y2_[j];
      const DATA_TYPE *Arow = A_ + (size_t)j * n; /* row j of A */

      for (i = 0; i < n_pb; i++)
        x2_[i] += Arow[i] * y2j;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
